<script setup lang="ts">
import type { Workspace } from '../../../shared/types'
const drive = useDrive()
const workspaces = computed(() => drive.workspaces.value)
const user = computed(() => drive.user.value)
const loading = ref(true), error = ref(''), creating = ref(false)
const { notify } = useNotify()
function open(workspace: Workspace) { return navigateTo(`/workspaces/${encodeURIComponent(workspace.id)}/files`) }
async function load() { loading.value = true; error.value = ''; try { await drive.refreshWorkspaces() } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Çalışma alanların alınamadı.' } finally { loading.value = false } }
async function more() { try { await drive.loadMoreWorkspaces() } catch { /* The shared pagination error is shown below. */ } }
function created(workspace: Workspace) { creating.value = false; notify('Çalışma alanın oluşturuldu. Owner rolündesin.'); void open(workspace) }
onMounted(load)
useHead({ title: 'Çalışma alanları · Ortak Drive' })
</script>
<template><div><div v-if="drive.mode.value === 'demo'" class="demo-banner"><span>Demo modundasın. Veriler bu sekmede tutulur; yenileyince örnek duruma döner. E-posta gönderilmez.</span><NuxtLink to="/invitations/accept">Davet akışını dene</NuxtLink></div><div class="page-heading"><div><p class="eyebrow">ÇALIŞMA ALANLARIN</p><h1 class="page-title">Hoş geldin, {{ user?.name.split(' ')[0] }}.</h1><p class="page-subtitle">Bir çalışma alanı seçerek kaldığın yerden devam et.</p></div><button class="btn btn-primary" @click="creating = true"><AppIcon name="plus" :size="19" />Yeni çalışma alanı</button></div><div v-if="loading" class="workspace-grid" aria-label="Çalışma alanları yükleniyor" aria-busy="true"><div v-for="n in 3" :key="n" class="workspace-card skeleton" /></div><div v-else-if="error" class="empty-state" role="alert"><AppIcon name="info" :size="35" /><h2>Alanlarını yükleyemedik.</h2><p>{{ error }}</p><button class="btn btn-primary" @click="load">Yeniden dene</button></div><div v-else-if="!workspaces.length" class="empty-state"><AppIcon name="folder" :size="40" /><h2>İlk çalışma alanına yer aç.</h2><p>Bir alan oluşturduğunda otomatik olarak Owner olursun.<br>Ardından takım arkadaşlarını davet edebilirsin.</p><button class="btn btn-primary" @click="creating = true">İlk alanı oluştur</button></div><div v-else class="workspace-grid"><button v-for="workspace in workspaces" :key="workspace.id" class="workspace-card" @click="open(workspace)"><span class="workspace-card-top"><span class="workspace-symbol" :style="{ backgroundColor: workspace.color + '18', color: workspace.color }"><AppIcon name="folder" :size="27" /></span><RoleBadge :role="workspace.role" /></span><h2>{{ workspace.name }}</h2><p>{{ workspace.description || 'Ekibinin ortak dosya alanı.' }}</p><span class="workspace-card-bottom"><span><AppIcon name="users" :size="15" />{{ workspace.memberCount }} üye</span><AppIcon name="arrow" :size="20" /></span></button><button class="workspace-card create-card" @click="creating = true"><span class="create-plus"><AppIcon name="plus" :size="29" /></span><strong>Yeni bir alan oluştur</strong><span>Yeni bir proje, yeni bir başlangıç.</span></button></div><div v-if="!loading && (workspaces.length || drive.workspaceNextCursor.value)" class="pagination-controls"><p v-if="drive.workspacePageError.value" class="form-error" role="alert">{{ drive.workspacePageError.value }} <button class="btn btn-secondary" @click="load">Listeyi yenile</button></p><button v-if="drive.workspaceNextCursor.value" type="button" class="btn btn-secondary" :disabled="drive.workspaceLoadingMore.value" @click="more">{{ drive.workspaceLoadingMore.value ? 'Yükleniyor…' : 'Daha fazla çalışma alanı' }}</button></div><div class="workspace-info"><AppIcon name="shield" :size="19" /><p>Her çalışma alanındaki rolün bağımsızdır. Bir alanda Owner, başka bir alanda Viewer olabilirsin.</p></div><WorkspaceCreator :open="creating" @close="creating = false" @created="created" /></div></template>
<style scoped>.pagination-controls{margin-top:24px;text-align:center}.workspace-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin-top:33px}.workspace-card{background:white;border:1px solid var(--line);border-radius:18px;min-height:242px;padding:25px;text-align:left;transition:box-shadow .15s,border-color .15s;display:flex;flex-direction:column;min-width:0}.workspace-card:hover{border-color:#9ab8e9;box-shadow:0 5px 20px #214c7d0c}.workspace-card-top{display:flex;align-items:center;justify-content:space-between;gap:12px}.workspace-symbol{display:grid;place-items:center;width:53px;height:53px;border-radius:14px}.workspace-card h2{font-size:19px;margin:25px 0 10px;font-weight:500;letter-spacing:-.4px}.workspace-card>p{font-size:13px;line-height:1.8;color:var(--muted);margin:0 0 24px}.workspace-card-bottom{display:flex;align-items:center;justify-content:space-between;color:#7e92ad;margin-top:auto}.workspace-card-bottom>span{display:flex;align-items:center;gap:7px;font-size:12px}.create-card{border-style:dashed;background:transparent;align-items:center;justify-content:center;text-align:center;gap:16px}.create-plus{display:grid;place-items:center;width:54px;height:54px;background:#e8f0fe;color:#4285f4;border-radius:50%;margin-bottom:3px}.create-card strong{font-size:15px;font-weight:400}.create-card>span:last-child{font-size:12px;color:var(--muted)}.workspace-info{display:flex;gap:10px;align-items:flex-start;margin-top:31px;color:#7b8ba2}.workspace-info svg{margin-top:1px}.workspace-info p{font-size:12px;line-height:1.8;margin:0}.skeleton{background:linear-gradient(110deg,#edf1f7 25%,#f9fbfe 40%,#edf1f7 60%);background-size:200% 100%;animation:skeleton 1.6s infinite}@keyframes skeleton{to{background-position:-200% 0}}@media(max-width:1000px){.workspace-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.workspace-grid{grid-template-columns:1fr;gap:15px;margin-top:25px}.workspace-card{padding:23px;min-height:220px}.workspace-card h2{margin-top:21px}.workspace-card-top .role-badge{font-size:10px}.create-card{min-height:180px}.workspace-info{font-size:11px}.demo-banner{flex-direction:column;gap:6px}}</style>
